input.command:
for i in $(seq 1 20); do
  status=$(gh pr checks 59 2>&1)
  state=$(echo "$status" | grep -E "moon ci" | awk '{print $2}')
  echo "[poll $i] moon ci: ${state:-pending}"
  case "$state" in
    pass) echo "GREEN"; break ;;
    fail|error) echo "FAILED"; echo "$status"; break ;;
    *) sleep 20 ;;
  esac
done

for i in $(seq 1 20); do
  out=$(gh pr checks 59 2>&1)
  state=$(echo "$out" | grep -E "moon ci" | awk '{print $2}')
  echo "[poll $i] moon ci: ${state:-pending}"
  case "$state" in
    pass) echo "GREEN"; break ;;
    fail|error) echo "FAILED"; echo "$out"; break ;;
    *) sleep 20 ;;
  esac
done

